package com.freerangepets;

import java.util.Arrays;

/**
 * Primitive {@code long -> long} hash map preserving insertion order, avoiding
 * boxed allocations during tile floods, pathfinding, and occupancy tracking.
 */
final class TileMap
{
	private static final long EMPTY = Long.MIN_VALUE;

	private long[] keys;
	private long[] values;
	private int mask;
	private long[] order;
	private int size;

	private boolean hasEmptyKey;
	private long emptyKeyValue;

	TileMap(int expected)
	{
		int capacity = Integer.highestOneBit(Math.max(4, expected) * 2 - 1) * 2;
		keys = new long[capacity];
		values = new long[capacity];
		Arrays.fill(keys, EMPTY);
		mask = capacity - 1;
		order = new long[Math.max(4, expected)];
	}

	int size()
	{
		return size;
	}

	long keyAt(int index)
	{
		return order[index];
	}

	boolean containsKey(long key)
	{
		if (key == EMPTY)
		{
			return hasEmptyKey;
		}
		for (int slot = slot(key); ; slot = (slot + 1) & mask)
		{
			long at = keys[slot];
			if (at == key)
			{
				return true;
			}
			if (at == EMPTY)
			{
				return false;
			}
		}
	}

	long getOrDefault(long key, long missing)
	{
		if (key == EMPTY)
		{
			return hasEmptyKey ? emptyKeyValue : missing;
		}
		for (int slot = slot(key); ; slot = (slot + 1) & mask)
		{
			long at = keys[slot];
			if (at == key)
			{
				return values[slot];
			}
			if (at == EMPTY)
			{
				return missing;
			}
		}
	}

	long get(long key)
	{
		if (key == EMPTY)
		{
			if (!hasEmptyKey)
			{
				throw new IllegalStateException("No such tile");
			}
			return emptyKeyValue;
		}
		for (int slot = slot(key); ; slot = (slot + 1) & mask)
		{
			long at = keys[slot];
			if (at == key)
			{
				return values[slot];
			}
			if (at == EMPTY)
			{
				throw new IllegalStateException("No such tile");
			}
		}
	}

	void add(long key, long value)
	{
		if (size == order.length)
		{
			order = Arrays.copyOf(order, size * 2);
		}
		order[size++] = key;
		if (key == EMPTY)
		{
			hasEmptyKey = true;
			emptyKeyValue = value;
			return;
		}
		if (size * 2 > keys.length)
		{
			grow();
		}
		insert(key, value);
	}

	long addTo(long key, long delta)
	{
		if (key == EMPTY)
		{
			if (!hasEmptyKey)
			{
				add(key, delta);
				return delta;
			}
			return emptyKeyValue += delta;
		}
		for (int slot = slot(key); ; slot = (slot + 1) & mask)
		{
			long at = keys[slot];
			if (at == key)
			{
				return values[slot] += delta;
			}
			if (at == EMPTY)
			{
				add(key, delta);
				return delta;
			}
		}
	}

	void clear()
	{
		if (size == 0)
		{
			return;
		}
		Arrays.fill(keys, EMPTY);
		size = 0;
		hasEmptyKey = false;
	}

	private void insert(long key, long value)
	{
		int slot = slot(key);
		while (keys[slot] != EMPTY)
		{
			slot = (slot + 1) & mask;
		}
		keys[slot] = key;
		values[slot] = value;
	}

	private void grow()
	{
		long[] oldKeys = keys;
		long[] oldValues = values;
		keys = new long[oldKeys.length * 2];
		values = new long[oldKeys.length * 2];
		Arrays.fill(keys, EMPTY);
		mask = keys.length - 1;
		for (int i = 0; i < oldKeys.length; i++)
		{
			if (oldKeys[i] != EMPTY)
			{
				insert(oldKeys[i], oldValues[i]);
			}
		}
	}

	private int slot(long key)
	{
		long h = key * 0x9E3779B97F4A7C15L;
		return (int) (h ^ (h >>> 32)) & mask;
	}
}

